#!/usr/bin/env python3
"""
Warudo .warudo plugin packager (no Unity required).
Packages a compiled DLL into a .warudo bundle.

Usage:
  python pack.py <plugin_name> <dll_path> [--version <ver>] [--author <author>] [--desc <desc>] [--output <path>]

Note: there is no --id flag. The plugin id lives in the [PluginType] attribute
in the DLL; it is not written to modinfo.dat.

Example:
  python pack.py HelloWorld output/HelloWorld.dll --version 1.0.0 --author Test
"""

import zipfile
import io
import struct
import time
import argparse
import base64
import uuid


UMOD_MAGIC      = b'UMOD'
UMOD_HEADER_UNK = b'\xf3\xf0\x1c\x04\x00\x00\x00\x00'
UMOD_VERSION    = '2.9.0'
UNITY_VERSION   = '2021.3.45f2'
SDK_VERSION     = '0.14.3'

# Minimal Unity asset bundle baked in — UMod requires sharedassets.bin even for code-only plugins.
# Source: World2Screen.warudo (contains only a Readme.txt, no game assets).
SHAREDASSETS_BIN  = base64.b64decode('')
SHAREDASSETS_META = base64.b64decode('E0Fzc2V0cy9Xb3JsZDJTY3JlZW4BAAAAHkFzc2V0cy9Xb3JsZDJTY3JlZW4vUmVhZG1lLnR4dA==')


def write_varint_string(s: str) -> bytes:
    """C# BinaryWriter.Write(string) — 7-bit VarInt length + UTF-8 bytes."""
    encoded = s.encode('utf-8')
    n = len(encoded)
    varint = []
    while n >= 0x80:
        varint.append((n & 0x7F) | 0x80)
        n >>= 7
    varint.append(n)
    return bytes(varint) + encoded


def make_modinfo(plugin_name: str, plugin_version: str, description: str = '', author: str = '') -> bytes:
    unix_now = time.time()
    filetime = int((unix_now + 11644473600) * 10_000_000)
    data  = UMOD_MAGIC + struct.pack('<Q', filetime)
    data += struct.pack('<III', 3, 4, 3)
    for s in (UMOD_VERSION, UNITY_VERSION, SDK_VERSION, plugin_name, plugin_version, description, author):
        data += write_varint_string(s)
    data += b'\x00\x00'
    return data


def pe_magic_int(dll: bytes) -> int:
    """SizeOfCode + SizeOfInitializedData + SizeOfHeaders from PE Optional Header."""
    e_lfanew = struct.unpack_from('<I', dll, 0x3c)[0]
    oh = e_lfanew + 0x18
    return (struct.unpack_from('<I', dll, oh + 0x04)[0] +
            struct.unpack_from('<I', dll, oh + 0x08)[0] +
            struct.unpack_from('<I', dll, oh + 0x3C)[0])


def make_assemblymodules(dll: bytes) -> bytes:
    name = f'umod-compiled-{uuid.uuid4()}'
    data  = struct.pack('<I', 1)               # count
    data += write_varint_string(name)
    data += write_varint_string('<Unknown>')
    data += struct.pack('<I', 1)               # EntryFlags.AssemblyImage (no debug symbols)
    data += struct.pack('<I', pe_magic_int(dll))
    data += dll
    return data


def pack_warudo(plugin_name: str, dll_path: str, version: str, author: str, description: str, output_path: str):
    with open(dll_path, 'rb') as f:
        dll = f.read()
    print(f'[pack] {dll_path} ({len(dll)} bytes)')

    zip_buf = io.BytesIO()
    # ZIP_STORED: UMod's SharpZipLib crashes on standard deflate streams
    with zipfile.ZipFile(zip_buf, 'w', zipfile.ZIP_STORED) as zf:
        zf.writestr('modinfo.dat',         make_modinfo(plugin_name, version, description, author))
        zf.writestr('sharedassets.bin',    SHAREDASSETS_BIN)
        zf.writestr('sharedassets.meta',   SHAREDASSETS_META)
        zf.writestr('assemblymodules.dat', make_assemblymodules(dll))

    final = UMOD_MAGIC + UMOD_HEADER_UNK + zip_buf.getvalue()
    with open(output_path, 'wb') as f:
        f.write(final)
    print(f'[pack] -> {output_path} ({len(final)} bytes)')


if __name__ == '__main__':
    p = argparse.ArgumentParser(description='Pack a DLL into a .warudo bundle')
    p.add_argument('plugin_name')
    p.add_argument('dll_path')
    p.add_argument('--version',  default='1.0.0')
    p.add_argument('--author',   default='')
    p.add_argument('--desc',     default='')
    p.add_argument('--output',   default='')
    args = p.parse_args()
    out = args.output or f'{args.plugin_name}.warudo'
    pack_warudo(args.plugin_name, args.dll_path, args.version, args.author, args.desc, out)
